<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php'; require_role('owner');
function recipe_redirect(string $message): never { $_SESSION['flash']=$message;redirect('/owner/recipes.php'); }
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf()){http_response_code(400);exit('Invalid request.');}$a=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($a==='delete'){$pdo->prepare('DELETE FROM recipes WHERE id=:id')->execute(['id'=>$id]);recipe_redirect('Recipe ingredient removed.');}$menu=(int)($_POST['menu_item_id']??0);$ingredient=(int)($_POST['ingredient_id']??0);$qty=filter_var($_POST['qty_per_item']??null,FILTER_VALIDATE_FLOAT);if($menu<1||$ingredient<1||$qty===false||$qty<=0){$_SESSION['form_error']='Choose a menu item and ingredient, then enter a quantity greater than zero.';redirect('/owner/recipes.php'.($id?'?edit='.$id:''));}$q=$pdo->prepare('SELECT id FROM menu_items WHERE id=:id');$q->execute(['id'=>$menu]);$okMenu=(bool)$q->fetch();$q=$pdo->prepare('SELECT id FROM ingredients WHERE id=:id');$q->execute(['id'=>$ingredient]);if(!$okMenu||!$q->fetch()){$_SESSION['form_error']='Choose existing records.';redirect('/owner/recipes.php'.($id?'?edit='.$id:''));}$q=$pdo->prepare('SELECT id FROM recipes WHERE menu_item_id=:m AND ingredient_id=:i AND id!=:id');$q->execute(['m'=>$menu,'i'=>$ingredient,'id'=>$id]);if($q->fetch()){$_SESSION['form_error']='This ingredient is already in that recipe.';redirect('/owner/recipes.php'.($id?'?edit='.$id:''));}if($a==='edit'&&$id){$pdo->prepare('UPDATE recipes SET menu_item_id=:m,ingredient_id=:i,qty_per_item=:q WHERE id=:id')->execute(['m'=>$menu,'i'=>$ingredient,'q'=>$qty,'id'=>$id]);recipe_redirect('Recipe updated.');}$pdo->prepare('INSERT INTO recipes(menu_item_id,ingredient_id,qty_per_item) VALUES(:m,:i,:q)')->execute(['m'=>$menu,'i'=>$ingredient,'q'=>$qty]);recipe_redirect('Recipe ingredient added.');}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM recipes WHERE id=:id');$q->execute(['id'=>(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$menus=$pdo->query('SELECT id,name FROM menu_items WHERE is_archived=0 ORDER BY name')->fetchAll();$ingredients=$pdo->query('SELECT id,name,unit FROM ingredients WHERE is_archived=0 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT r.*,m.name menu_name,i.name ingredient_name,i.unit FROM recipes r JOIN menu_items m ON m.id=r.menu_item_id JOIN ingredients i ON i.id=r.ingredient_id ORDER BY m.name,i.name')->fetchAll();$page_title='Recipes';$theme='owner';require __DIR__.'/../includes/header.php';
?><main class="app-owner-page"><div class="app-page-heading"><div><p class="eyebrow">Owner tools</p><h1>Recipes<span>.</span></h1></div></div><?php if(!empty($_SESSION['flash'])):?><p class="app-message app-message-success"><?=e((string)$_SESSION['flash']);unset($_SESSION['flash']);?></p><?php endif;?><section class="app-admin-grid"><form method="post" class="app-form-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif;?><h2><?=$edit?'Edit recipe row':'Add recipe row'?></h2><?php if(!empty($_SESSION['form_error'])):?><p class="app-form-error"><?=e((string)$_SESSION['form_error']);unset($_SESSION['form_error']);?></p><?php endif;?><label class="app-field">Menu item<select name="menu_item_id" required><option value="">Choose item</option><?php foreach($menus as $m):?><option value="<?=(int)$m['id']?>" <?=((int)($edit['menu_item_id']??0)===(int)$m['id'])?'selected':''?>><?=e($m['name'])?></option><?php endforeach;?></select></label><label class="app-field">Ingredient<select name="ingredient_id" required><option value="">Choose ingredient</option><?php foreach($ingredients as $i):?><option value="<?=(int)$i['id']?>" <?=((int)($edit['ingredient_id']??0)===(int)$i['id'])?'selected':''?>><?=e($i['name'].' ('.$i['unit'].')')?></option><?php endforeach;?></select></label><label class="app-field">Quantity per item<input name="qty_per_item" type="number" min="0.001" step="0.001" required value="<?=e((string)($edit['qty_per_item']??''))?>"></label><button class="primary-button">Save recipe row</button></form><section class="app-list-card"><div class="app-table-wrap"><table class="app-table"><thead><tr><th>Menu item</th><th>Ingredient</th><th>Quantity</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['menu_name'])?></td><td><?=e($r['ingredient_name'])?><small><?=e($r['unit'])?></small></td><td><?=e((string)$r['qty_per_item'])?></td><td><a class="app-table-link" href="?edit=<?=(int)$r['id']?>">Edit</a><form method="post" class="app-inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="delete"><button class="app-table-link">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div></section></section></main><?php require __DIR__.'/../includes/footer.php';?>
